    const CIFRA = [String(F.length), deD.length && deD[0].dato ? nb(deD[0].dato.txt) : '?', String(tardesVistas), String(INS.filter(g => g.ve).length),
      String(Pn.filter(q => q.ve).length), String(nPreg)][n];
