    r.push([GE.ve === E.pleito, `paso ${n}: ${E.pleito ? 'están las dos personas del pleito' : 'todavía no hay pleito'}`, GE.ve]);
    const cabezas = GE.personas.map(p => p.cabeza.c), medio = (cabezas[0][0] + cabezas[1][0]) / 2;
