    const medio = c => [(c.x0 + c.x1) / 2, (c.y0 + c.y1) / 2];
    /* La libreta, renglón por renglón, de izquierda a derecha. */
    const renglon = k => x.renglones.filter(t => t.r === k).sort((a, b) => a.caja.x0 - b.caja.x0).map(t => nb(t.dice)).join(' ');
